protected override void OnModelCreating(ModelBuilder b)
{
    // 1) Default: int identity — fine for a monolith's own database
    b.Entity<Order>(e =>
    {
        e.HasKey(o => o.Id);
        e.Property(o => o.Id).UseIdentityColumn();
    });

    // 2) Sequential GUID: client-assignable, index-friendly (SQL Server)
    b.Entity<Event>(e =>
    {
        e.HasKey(x => x.Id);
        e.Property(x => x.Id)
          .HasDefaultValueSql("NEWSEQUENTIALID()");   // DB-side, time-ordered
    });

    // .NET 8+: also fine to assign Guid.CreateVersion7() in app code
    // var id = Guid.CreateVersion7();   // time-ordered by construction

    // 3) HiLo: integers, allocated in blocks, assigned before INSERT
    b.Entity<Comment>(e =>
    {
        e.HasKey(c => c.Id);
        e.Property(c => c.Id).UseHiLo("CommentHiLo");
    });

    // 4) Immutable business surrogate: never generate, app assigns
    b.Entity<Sku>().Property(s => s.Code).ValueGeneratedNever();

    // 5) Keyless projection entity — read-only, not saved
    b.Entity<SalesSummary>().HasNoKey().ToView("vw_SalesByDay");
}

// Rule of thumb:
// single DB, no key in URLs          → int/bigint identity
// distributed inserts / keys in URLs → sequential GUID (v7 or DB function)
// high-rate insert, no round-trips   → HiLo / sequence
